export async function simulateTransactions(params: {
  chain?: string;
  from: string;
  transactions: Array<{ to: string; data: string; value?: string }> | string;
  analysisContext?: unknown;
}): Promise<OkRead | ToolError> {
  const chainResult = resolveChain(params.chain);
  if ('status' in chainResult) return chainResult;
  const fromErr = validateEvmAddress(params.from, 'from');
  if (fromErr) return fromErr;
  if (params.transactions === undefined || params.transactions === null) {
    return { status: 'error', error_code: 'MISSING_PARAM', message: '`transactions` is required.' };
  }
  const txJson =
    typeof params.transactions === 'string' ? params.transactions : JSON.stringify(params.transactions);
  const ctxJson =
    params.analysisContext === undefined
      ? undefined
      : typeof params.analysisContext === 'string'
        ? (params.analysisContext as string)
        : JSON.stringify(params.analysisContext);
  return safe(() => {
    const data = invokeMorphoCli('simulate-transactions', {
      chain: chainResult.name,
      from: lc(params.from),
      transactions: txJson,
      'analysis-context': ctxJson,
    });
    return { status: 'ok' as const, chain: chainResult.name, data };
  });
}

// =============================================================================
