export async function prepareDeposit(params: {
  chain?: string;
  vaultAddress: string;
  userAddress: string;
  amount: string;
  noSimulate?: boolean;
}): Promise<PendingSign | ToolError> {
  const chainResult = resolveChain(params.chain);
  if ('status' in chainResult) return chainResult;
  const err =
    validateEvmAddress(params.vaultAddress, 'vaultAddress') ??
    validateEvmAddress(params.userAddress, 'userAddress') ??
    validatePositiveAmount(params.amount, 'amount');
  if (err) return err;
  const prepResult = safe(() =>
    invokeMorphoCli<PreparedOperation>('prepare-deposit', {
      chain: chainResult.name,
      'vault-address': lc(params.vaultAddress),
      'user-address': lc(params.userAddress),
      amount: params.amount,
      ...(params.noSimulate ? { 'no-simulate': '' } : {}),
    }),
  );
  if (typeof prepResult === 'object' && prepResult !== null && 'status' in prepResult && prepResult.status === 'error') {
    return prepResult as ToolError;
  }
  return preparedToPendingSign(prepResult as PreparedOperation, 'prepareDeposit', chainResult.name);
}

