export async function prepareBorrow(params: {
  chain?: string;
  marketId: string;
  userAddress: string;
  borrowAmount: string;
  noSimulate?: boolean;
}): Promise<PendingSign | ToolError> {
  const chainResult = resolveChain(params.chain);
  if ('status' in chainResult) return chainResult;
  const err =
    validate32ByteHash(params.marketId, 'marketId') ??
    validateEvmAddress(params.userAddress, 'userAddress') ??
    validatePositiveAmount(params.borrowAmount, 'borrowAmount');
  if (err) return err;
  const prepResult = safe(() =>
    invokeMorphoCli<PreparedOperation>('prepare-borrow', {
      chain: chainResult.name,
      'market-id': params.marketId.toLowerCase(),
      'user-address': lc(params.userAddress),
      'borrow-amount': params.borrowAmount,
      ...(params.noSimulate ? { 'no-simulate': '' } : {}),
    }),
  );
  if (typeof prepResult === 'object' && prepResult !== null && 'status' in prepResult && prepResult.status === 'error') {
    return prepResult as ToolError;
  }
  const prepared = prepResult as PreparedOperation;
  const market = (prepared.outcome?.market ?? {}) as { healthFactor?: string; isHealthy?: boolean };
  if (market.healthFactor !== undefined) {
    const hf = Number(market.healthFactor);
    if (!Number.isNaN(hf) && hf < 1.0) {
      return {
        status: 'error',
        error_code: 'HEALTH_FACTOR_TOO_LOW',
        message: `Borrow would drop health factor to ${market.healthFactor} (< 1.0 is liquidatable).`,
        suggestion: 'Reduce the borrow amount or supply more collateral first.',
        details: { simulationSummary: prepared.summary },
      };
    }
  }
  return preparedToPendingSign(prepared, 'prepareBorrow', chainResult.name);
}

